package me.pikanote.companion;
import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.security.MessageDigest;import java.util.*;import java.util.zip.*;
final class PhoneBackup{
 static void write(Store store,OutputStream output)throws Exception{write(store,output,false);}
 static void write(Store store,OutputStream output,boolean complete)throws Exception{
  final JSONObject manifest;final JSONArray files=new JSONArray();
  synchronized(store){PhoneAsk.importFeed(store);JSONObject state=new JSONObject(store.state.toString());state.remove("pin");state.remove("appPin");state.remove("appLock");if(!complete)state.remove("settingsSecrets");state.remove("ownerKey");state.remove("deviceSerial");state.remove("device");state.remove("onboardingComplete");state.remove("forgetIntent");if(complete&&state.optJSONObject("deviceSecrets")==null)throw new IOException("Connect Pika once to back up all settings and credentials");JSONArray q=state.getJSONArray("pending");for(int i=q.length()-1;i>=0;i--)if(!complete&&q.getJSONObject(i).getString("path").equals("/api/manager/settings"))q.remove(i);manifest=new JSONObject().put("format","pika-phone").put("version",complete?2:1).put("includesCredentials",complete).put("state",state);Iterator<String> names=state.getJSONObject("files").keys();while(names.hasNext()){String name=names.next();File f=store.safeFile(name);if(!f.isFile())throw new IOException("Backup file not available: "+name+". Sync with Pika first.");files.put(new JSONObject().put("name",name).put("size",f.length()).put("sha256",state.getJSONObject("files").getString(name)));}JSONArray voices=state.optJSONArray("voiceCaptures");if(voices!=null)for(int i=0;i<voices.length();i++){JSONObject capture=voices.getJSONObject(i);if(capture.optBoolean("hidden"))continue;String name=capture.getString("file");if(state.getJSONObject("files").has(name))continue;File file=store.safeFile(name);if(!file.isFile())throw new IOException("Phone voice recording missing; backup stopped");files.put(new JSONObject().put("name",name).put("size",file.length()).put("sha256",PhoneVoice.hash(file)));}JSONArray asks=state.optJSONArray("askTurns");if(asks!=null)for(int i=0;i<asks.length();i++){String name=asks.getJSONObject(i).optString("wav");if(name.isEmpty()||state.getJSONObject("files").has(name))continue;File f=store.safeFile(name);if(!f.isFile())continue;files.put(new JSONObject().put("name",name).put("size",f.length()).put("sha256",PhoneVoice.hash(f)));}manifest.put("files",files);}
  // No Store lock while compressing or writing to a slow cloud provider. A
  // concurrent mirror replacement must fail checksum rather than mix versions.
  try(ZipOutputStream zip=new ZipOutputStream(output)){zip.putNextEntry(new ZipEntry("pika-phone.json"));zip.write(manifest.toString().getBytes(StandardCharsets.UTF_8));zip.closeEntry();for(int i=0;i<files.length();i++){JSONObject metadata=files.getJSONObject(i);String name=metadata.getString("name");zip.putNextEntry(new ZipEntry("notes/"+name));MessageDigest digest=MessageDigest.getInstance("SHA-256");long count=0;try(InputStream in=new FileInputStream(store.safeFile(name))){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))>=0){if(n==0)continue;count+=n;digest.update(buffer,0,n);zip.write(buffer,0,n);}}if(count!=metadata.getLong("size")||!BleTransport.hex(digest.digest()).equals(metadata.getString("sha256")))throw new IOException("Library changed during backup. Wait for sync, then retry.");zip.closeEntry();}}
 }
 static void restore(Store store,InputStream input)throws Exception{
  PikaService service=PikaService.instance;if(service!=null&&service.syncing)throw new IOException("Wait until current synchronization finishes");File root=new File(store.context.getFilesDir(),"restore-stage");remove(root);root.mkdirs();JSONObject manifest=null;Map<String,JSONObject> expected=new HashMap<>();Set<String> got=new HashSet<>();long total=0;
  try{try(ZipInputStream zip=new ZipInputStream(input)){ZipEntry entry;while((entry=zip.getNextEntry())!=null){String name=entry.getName();if(entry.isDirectory())continue;
    if(manifest==null){if(!BrandCompatibility.is(name,"pika-phone.json"))throw new IOException("Choose a Pika Companion ZIP");ByteArrayOutputStream data=new ByteArrayOutputStream();copyBounded(zip,data,4*1024*1024);manifest=new JSONObject(data.toString("UTF-8"));if(!BrandCompatibility.is(manifest.optString("format"),"pika-phone")||(manifest.optInt("version")!=1&&manifest.optInt("version")!=2))throw new IOException("Unsupported backup");JSONArray list=manifest.getJSONArray("files");if(list.length()>4096)throw new IOException("Too many files");for(int i=0;i<list.length();i++){JSONObject f=list.getJSONObject(i);String key=f.getString("name");store.safeFile(key);if(expected.put(key,f)!=null||!f.getString("sha256").matches("[a-f0-9]{64}"))throw new IOException("Invalid file list");}continue;}
    if(!name.startsWith("notes/"))throw new IOException("Invalid backup path");String relative=name.substring(6);JSONObject f=expected.get(relative);if(f==null||!got.add(relative))throw new IOException("Unexpected duplicate file");long size=f.getLong("size");total+=size;if(size<0||size>2L*1024*1024*1024||total>2L*1024*1024*1024||root.getUsableSpace()<size+1048576)throw new IOException("Not enough phone storage");store.safeFile(relative);File target=new File(root,relative);target.getParentFile().mkdirs();MessageDigest sha=MessageDigest.getInstance("SHA-256");long count=0;try(OutputStream out=new FileOutputStream(target)){byte[] buf=new byte[8192];int n;while((n=zip.read(buf))>=0){if(n==0)continue;count+=n;if(count>size)throw new IOException("Oversize backup file");sha.update(buf,0,n);out.write(buf,0,n);}}if(count!=size||!BleTransport.hex(sha.digest()).equals(f.getString("sha256")))throw new IOException("Backup checksum failed");
   }}if(manifest==null||got.size()!=expected.size()||!expected.containsKey("index.csv"))throw new IOException("Incomplete backup");JSONObject next=manifest.getJSONObject("state");next.remove("forgetIntent");if(next.optJSONObject("deviceSecrets")!=null)next.put("restoreDeviceSecrets",new JSONObject(next.getJSONObject("deviceSecrets").toString()));next.getJSONObject("snapshot").getJSONArray("memories");next.getJSONArray("pending");synchronized(store){next.put("ownerKey",store.state.optString("ownerKey")).put("deviceSerial",store.state.optString("deviceSerial")).put("onboardingComplete",true).put("appPin",store.state.optString("appPin")).put("appLock",store.state.optBoolean("appLock")).put("pin",store.pin()).put("device",store.state.optString("device")).put("restorePending",true).put("restoreAuthorized",false);Vault.write(new File(store.context.getFilesDir(),"restore-state.aes"),next.toString().getBytes(StandardCharsets.UTF_8));File marker=new File(store.context.getFilesDir(),"restore-intent");Files.write(marker.toPath(),new byte[]{1});recover(store.context.getFilesDir());store.state=next;store.syncMessage="Restored phone library · tap Sync to confirm device replacement";}
  }catch(Exception e){if(!new File(store.context.getFilesDir(),"restore-intent").exists())remove(root);throw e;}
 }
 static void recover(File files)throws Exception{File marker=new File(files,"restore-intent");if(!marker.exists())return;File stage=new File(files,"restore-stage"),notes=new File(files,"notes"),old=new File(files,"restore-old");if(stage.exists()){if(notes.exists()){if(old.exists())remove(old);Files.move(notes.toPath(),old.toPath(),StandardCopyOption.ATOMIC_MOVE);}Files.move(stage.toPath(),notes.toPath(),StandardCopyOption.ATOMIC_MOVE);}File state=new File(files,"restore-state.aes");if(state.exists()){Vault.write(new File(files,"phone-store.aes"),Vault.read(state));state.delete();}marker.delete();}
 static void copyBounded(InputStream in,OutputStream out,int max)throws IOException{byte[] buf=new byte[8192];int count=0,n;while((n=in.read(buf))>=0){count+=n;if(count>max)throw new IOException("Metadata too large");out.write(buf,0,n);}}
 static void remove(File file)throws IOException{if(!file.exists())return;if(file.isDirectory()){File[] children=file.listFiles();if(children==null)throw new IOException("Cannot inspect restore folder");for(File child:children)remove(child);}if(!file.delete())throw new IOException("Could not clean restore staging");}
}
